"  const handleSelectWaiter = (waiter) => {
    setSelectedWaiter(waiter);
    if (selectedTable) {
      setTableWaiters(prev => ({ ...prev, [selectedTable.id]: waiter }));
    }
  };

  const refreshDiscounts = async () => {
    try {
      const outletId = business?.user_id || business?.parent_user_id || business?.id;
      if (!outletId) return;
      const discountRes = await posService.getDiscounts(outletId);
      setAvailableDiscounts((discountRes.data || []).filter(d => d.is_active));
      localStorage.setItem('pos_discounts', JSON.stringify(discountRes.data || []));
    } catch (e) {
      console.warn("refreshDiscounts failed:", e);
    }
  };

